                    </CardContent>
                  </Card>
                )}
                {/* Main proposal content */}
                <Card className={idea.proposal_sections ? "lg:col-span-3" : "lg:col-span-4"}>
                  <CardContent className="pt-6">
                    {idea.proposal_sections && typeof idea.proposal_sections === "object" ? (
