                            {typeof value === "string" ? (
                              <MarkdownRenderer content={value} />
                            ) : Array.isArray(value) ? (
                              <div className="space-y-2">
                                {value.map((item: unknown, idx: number) => (
                                  <div key={idx} className="text-sm">
